import React, { useState } from "react";
import { Link } from "react-router-dom";
import { toast } from "react-toastify";
import authService from "../services/authService";

export default function ForgotPasswordPage() {
  const [email, setEmail] = useState("");
  const [loading, setLoading] = useState(false);
  const [sent, setSent] = useState(false);

  const handleSubmit = async (e) => {
    e.preventDefault();
    setLoading(true);
    try {
      const res = await authService.forgotPassword(email);
      toast.success(res.data.message);
      setSent(true);
    } catch (err) {
      toast.error(err.response?.data?.message || "Có lỗi xảy ra, vui lòng thử lại");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="min-h-[70vh] flex items-center justify-center px-4">
      <div className="w-full max-w-md bg-white border border-gray-200 rounded-xl p-8">
        <h1 className="font-display text-2xl text-ink mb-2">Quên mật khẩu?</h1>
        <p className="text-sm text-steel mb-6">
          Nhập email đã đăng ký, chúng tôi sẽ gửi cho bạn liên kết để đặt lại mật khẩu.
        </p>

        {sent ? (
          <div className="text-sm text-green-600 bg-green-50 border border-green-100 rounded-md p-4">
            Nếu email của bạn tồn tại trong hệ thống, một liên kết đặt lại mật khẩu đã được gửi.
            Vui lòng kiểm tra hộp thư (kể cả mục spam).
          </div>
        ) : (
          <form onSubmit={handleSubmit} className="space-y-4">
            <div>
              <label className="block text-sm font-medium text-ink mb-1">Email</label>
              <input
                type="email"
                value={email}
                onChange={(e) => setEmail(e.target.value)}
                required
                className="w-full border border-gray-300 rounded-md px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-ember"
              />
            </div>
            <button
              type="submit"
              disabled={loading}
              className="w-full bg-ember text-white font-semibold py-2.5 rounded-md hover:brightness-95 transition disabled:opacity-60"
            >
              {loading ? "Đang gửi..." : "Gửi liên kết đặt lại mật khẩu"}
            </button>
          </form>
        )}

        <p className="text-sm text-steel text-center mt-6">
          <Link to="/login" className="text-ember font-semibold hover:underline">
            ← Quay lại đăng nhập
          </Link>
        </p>
      </div>
    </div>
  );
}
